typedef unsigned long long ULL;

typedef struct {
    ULL bits[4]; /* 256 bits */
} Set256;

static Set256 set_empty(void) {
    Set256 s;
    s.bits[0] = s.bits[1] = s.bits[2] = s.bits[3] = 0;
    return s;
}

static Set256 set_full(void) {
    Set256 s;
    s.bits[0] = s.bits[1] = s.bits[2] = s.bits[3] = ~0ULL;
    return s;
}

static int set_has(const Set256 *s, int x) {
    return (s->bits[x >> 6] >> (x & 63)) & 1ULL;
}

static void set_add(Set256 *s, int x) {
    s->bits[x >> 6] |= 1ULL << (x & 63);
}

static int set_contains_zero(const Set256 *s) {
    return (s->bits[0] & 1ULL) != 0;
}

static int set_count(const Set256 *s) {
    return __builtin_popcountll(s->bits[0]) +
           __builtin_popcountll(s->bits[1]) +
           __builtin_popcountll(s->bits[2]) +
           __builtin_popcountll(s->bits[3]);
}

static Set256 op_add(Set256 a, Set256 b) {
    Set256 r = set_empty();
    for (int i = 0; i < 256; i++) if (set_has(&a, i)) {
        for (int j = 0; j < 256; j++) if (set_has(&b, j)) {
            set_add(&r, (i + j) & 255);
        }
    }
    return r;
}

static Set256 op_sub(Set256 a, Set256 b) {
    Set256 r = set_empty();
    for (int i = 0; i < 256; i++) if (set_has(&a, i)) {
        for (int j = 0; j < 256; j++) if (set_has(&b, j)) {
            set_add(&r, (i - j) & 255);
        }
    }
    return r;
}

static Set256 op_mul(Set256 a, Set256 b) {
    Set256 r = set_empty();
    for (int i = 0; i < 256; i++) if (set_has(&a, i)) {
        for (int j = 0; j < 256; j++) if (set_has(&b, j)) {
            set_add(&r, (i * j) & 255);
        }
    }
    return r;
}

static Set256 op_div(Set256 a, Set256 b) {
    Set256 r = set_empty();
    for (int i = 0; i < 256; i++) if (set_has(&a, i)) {
        for (int j = 1; j < 256; j++) if (set_has(&b, j)) {
            set_add(&r, i / j);
        }
    }
    return r;
}

int main(void) {
    char token[100005];
    Set256 stack[100005];
    int top = 0;
    int bad = 0;

    while (scanf("%100000s", token) == 1) {
        if (strlen(token) == 1 &&
            (token[0] == '+' || token[0] == '-' || token[0] == '*' || token[0] == '/')) {
            if (top < 2) {
                bad = 1;
                break;
            }
            Set256 b = stack[--top];
            Set256 a = stack[--top];
            Set256 r;

            if (token[0] == '+') r = op_add(a, b);
            else if (token[0] == '-') r = op_sub(a, b);
            else if (token[0] == '*') r = op_mul(a, b);
            else {
                if (set_contains_zero(&b)) {
                    bad = 1;
                    break;
                }
                r = op_div(a, b);
            }
            stack[top++] = r;
        } else {
            /* Any operand may be any 8-bit unsigned integer */
            stack[top++] = set_full();
        }
    }

    if (!bad && top != 1) bad = 1;

    puts(bad ? "correct" : "incorrect");
    return 0;
}

