public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null && !line.isEmpty()) {
            String[] tokens = line.split("\\s+");
            if (tokens.length == 0) continue;

            // Stack stores the possible ranges as [low, high] inclusive
            Deque<int[]> stack = new ArrayDeque<>();
            boolean possibleDivByZero = false;

            for (String token : tokens) {
                if (token.equals("+") || token.equals("-") || token.equals("*") || token.equals("/")) {
                    if (stack.size() < 2) {
                        // Invalid expression, but according to problem we assume valid
                        continue;
                    }
                    int[] b = stack.pop();
                    int[] a = stack.pop();
                    int[] result = new int[2];

                    if (token.equals("+")) {
                        // All possible sums mod 256
                        // We can compute min and max possible values
                        int min = (a[0] + b[0]) & 0xFF;
                        int max = (a[1] + b[1]) & 0xFF;
                        // However, due to overflow, the range might wrap around
                        // We need to consider all combinations
                        result = computeAddRange(a, b);
                    } else if (token.equals("-")) {
                        result = computeSubRange(a, b);
                    } else if (token.equals("*")) {
                        result = computeMulRange(a, b);
                    } else if (token.equals("/")) {
                        // Division: check if any possible b value is 0
                        if (b[0] == 0 || b[1] == 0 || (b[0] <= 0 && b[1] >= 0)) {
                            // There is a zero in the range
                            // But we need to check if zero is actually possible
                            // Since values are unsigned 8-bit, range is [0,255]
                            // If the range includes 0, division by zero is possible
                            possibleDivByZero = true;
                        }
                        // Compute result range for division (excluding zero)
                        result = computeDivRange(a, b);
                    }
                    stack.push(result);
                } else {
                    // Number
                    int val = Integer.parseInt(token) & 0xFF;
                    stack.push(new int[]{val, val});
                }
            }

            if (possibleDivByZero) {
                System.out.println("error");
            } else {
                System.out.println("correct");
            }
        }
    }

    // All functions return [min, max] possible values (mod 256, inclusive)
    // For simplicity, we compute exact min and max over all combinations,
    // considering that the actual set may not be contiguous, but for this problem
    // we only care about whether zero is possible in division.
    // We'll compute the full range by checking all possible values.

    static int[] computeAddRange(int[] a, int[] b) {
        int min = 255, max = 0;
        for (int va = a[0]; va <= a[1]; va++) {
            for (int vb = b[0]; vb <= b[1]; vb++) {
                int res = (va + vb) & 0xFF;
                if (res < min) min = res;
                if (res > max) max = res;
            }
        }
        return new int[]{min, max};
    }

    static int[] computeSubRange(int[] a, int[] b) {
        int min = 255, max = 0;
        for (int va = a[0]; va <= a[1]; va++) {
            for (int vb = b[0]; vb <= b[1]; vb++) {
                int res = (va - vb) & 0xFF;
                if (res < min) min = res;
                if (res > max) max = res;
            }
        }
        return new int[]{min, max};
    }

    static int[] computeMulRange(int[] a, int[] b) {
        int min = 255, max = 0;
        for (int va = a[0]; va <= a[1]; va++) {
            for (int vb = b[0]; vb <= b[1]; vb++) {
                int res = (va * vb) & 0xFF;
                if (res < min) min = res;
                if (res > max) max = res;
            }
        }
        return new int[]{min, max};
    }

    static int[] computeDivRange(int[] a, int[] b) {
        // Division by zero is not computed; we just return a range ignoring zero.
        int min = 255, max = 0;
        boolean hasValue = false;
        for (int va = a[0]; va <= a[1]; va++) {
            for (int vb = b[0]; vb <= b[1]; vb++) {
                if (vb == 0) continue;
                int res = (va / vb) & 0xFF;
                if (!hasValue) {
                    min = res;
                    max = res;
                    hasValue = true;
                } else {
                    if (res < min) min = res;
                    if (res > max) max = res;
                }
            }
        }
        if (!hasValue) {
            // All divisors were zero, but this case would already be caught
            return new int[]{0, 0};
        }
        return new int[]{min, max};
    }
}

