public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static class State {
        BitSet possible; // possible values 0..255
        boolean danger;  // whether division by zero may already happen inside this subexpression

        State() {
            possible = new BitSet(256);
            danger = false;
        }

        static State number(int v) {
            State s = new State();
            s.possible.set(v & 255);
            return s;
        }
    }

    static State apply(State a, State b, char op) {
        State res = new State();
        res.danger = a.danger || b.danger;

        if (op == '+') {
            for (int x = a.possible.nextSetBit(0); x >= 0; x = a.possible.nextSetBit(x + 1)) {
                for (int y = b.possible.nextSetBit(0); y >= 0; y = b.possible.nextSetBit(y + 1)) {
                    res.possible.set((x + y) & 255);
                }
            }
        } else if (op == '-') {
            for (int x = a.possible.nextSetBit(0); x >= 0; x = a.possible.nextSetBit(x + 1)) {
                for (int y = b.possible.nextSetBit(0); y >= 0; y = b.possible.nextSetBit(y + 1)) {
                    res.possible.set((x - y) & 255);
                }
            }
        } else if (op == '*') {
            for (int x = a.possible.nextSetBit(0); x >= 0; x = a.possible.nextSetBit(x + 1)) {
                for (int y = b.posible.nextSetBit(0); y >= 0; y = b.possible.nextSetBit(y + 1)) {
                    res.possible.set((x * y) & 255);
                }
            }
        } else { // '/'
            if (b.possible.get(0)) res.danger = true;
            for (int x = a.possible.nextSetBit(0); x >= 0; x = a.possible.nextSetBit(x + 1)) {
                for (int y = b.possible.nextSetBit(1); y >= 0; y = b.possible.nextSetBit(y + 1)) {
                    res.possible.set(x / y);
                }
            }
        }
        return res;
    }

    static boolean isOperator(String s) {
        return s.length() == 1 && "+-*/".indexOf(s.charAt(0)) >= 0;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        List<String> tokens = new ArrayList<>();
        String t;
        while ((t = fs.next()) != null) tokens.add(t);

        Deque<State> stack = new ArrayDeque<>();

        for (String tok : tokens) {
            if (isOperator(tok)) {
                State b = stack.pop();
                State a = stack.pop();
                stack.push(apply(a, b, tok.charAt(0)));
            } else {
                if (tok.equals("?")) {
                    State s = new State();
                    s.possible.set(0, 256);
                    stack.push(s);
                } else {
                    int v = Integer.parseInt(tok);
                    stack.push(State.number(v));
                }
            }
        }

        State ans = stack.pop();
        System.out.println(ans.danger ? "correct" : "incorrect");
    }
}
